import{_ as t,c as a,o as i,aj as o}from"./chunks/framework.D26WZD1w.js";const m=JSON.parse('{"title":"🏥 Medical Treatment Process During Winter/Summer Breaks Away from Zhuhai","description":"","frontmatter":{"comment":false},"headers":[],"relativePath":"en-us/workflows/medical.md","filePath":"en-us/workflows/medical.md","lastUpdated":1785552058000}'),n={name:"en-us/workflows/medical.md"};function r(s,e,l,c,d,u){return i(),a("div",null,e[0]||(e[0]=[o('<h1 id="🏥-medical-treatment-process-during-winter-summer-breaks-away-from-zhuhai" tabindex="-1">🏥 Medical Treatment Process During Winter/Summer Breaks Away from Zhuhai <a class="header-anchor" href="#🏥-medical-treatment-process-during-winter-summer-breaks-away-from-zhuhai" aria-label="Permalink to &quot;🏥 Medical Treatment Process During Winter/Summer Breaks Away from Zhuhai&quot;">​</a></h1><div class="danger custom-block"><p class="custom-block-title">Notice</p><p>This process is for BNBU students who need to receive medical treatment outside of Zhuhai. Please follow the steps below to complete the &quot;Medical Treatment Away from Place of Insurance&quot; registration (异地就医备案).</p></div><h2 id="pre-requisites" tabindex="-1">Pre-requisites <a class="header-anchor" href="#pre-requisites" aria-label="Permalink to &quot;Pre-requisites&quot;">​</a></h2><p>If choosing online operation, you can add <strong>BNBU Medical and Health Education Center</strong> WeChat: <strong>a13928025919</strong> If choosing offline operation, please go to <strong>BNBU Medical Center</strong> to pick up the forms.</p><h2 id="step-1-designating-a-primary-medical-institution" tabindex="-1">Step 1: Designating a Primary Medical Institution <a class="header-anchor" href="#step-1-designating-a-primary-medical-institution" aria-label="Permalink to &quot;Step 1: Designating a Primary Medical Institution&quot;">​</a></h2><p>Complete the outpatient selection registration in WeChat to set the school medical center as your designated medical institution.</p><h3 id="steps-for-selection" tabindex="-1">Steps for Selection <a class="header-anchor" href="#steps-for-selection" aria-label="Permalink to &quot;Steps for Selection&quot;">​</a></h3><ol><li>Open <strong>WeChat Mini Program</strong></li><li>Search and enter <strong>Zhuhai Social Security Mobile Office</strong> (珠海社保掌上办)</li><li>Select <strong>Medical and Maternity Insurance</strong> (医疗生育保险)</li><li>Click <strong>Outpatient Selection Registration</strong> (门诊选点登记)</li><li>Select <strong>Add New Selection</strong> (新增选点)</li><li>Select <strong>Outpatient Pooling Selection</strong> (门诊统筹选点)</li><li>Select Area: <strong>High-tech Industrial Development Zone</strong> (高新技术产业开发区)</li><li>Select Institution: <strong>BNBU Medical Center</strong> (北师香港浸会大学医务室)</li></ol><h2 id="step-2-obtaining-and-filling-out-the-registration-form" tabindex="-1">Step 2: Obtaining and Filling Out the Registration Form <a class="header-anchor" href="#step-2-obtaining-and-filling-out-the-registration-form" aria-label="Permalink to &quot;Step 2: Obtaining and Filling Out the Registration Form&quot;">​</a></h2><ol><li>Obtain the <strong>Medical Treatment Away from Place of Insurance Registration Form</strong> (异地就医备案表) online via WeChat or offline.</li><li>Fill out the form truthfully.</li><li>Return the completed form to the <strong>Medical and Health Education Center for stamping</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">Note</p><p>The stamping process usually takes 3-5 working days. Please be patient. The medical center will notify you to collect the form after stamping.</p></div><h2 id="step-3-applying-for-medical-treatment-away-from-place-of-insurance" tabindex="-1">Step 3: Applying for &quot;Medical Treatment Away from Place of Insurance&quot; <a class="header-anchor" href="#step-3-applying-for-medical-treatment-away-from-place-of-insurance" aria-label="Permalink to &quot;Step 3: Applying for &quot;Medical Treatment Away from Place of Insurance&quot;&quot;">​</a></h2><p>Complete the application in the WeChat Mini Program.</p><h3 id="application-steps" tabindex="-1">Application Steps <a class="header-anchor" href="#application-steps" aria-label="Permalink to &quot;Application Steps&quot;">​</a></h3><ol><li>Open <strong>WeChat Mini Program</strong></li><li>Search and enter <strong>Zhuhai Social Security Mobile Office</strong> (珠海社保掌上办)</li><li>Select <strong>Medical and Maternity Insurance</strong> (医疗生育保险)</li><li>Click <strong>Medical Treatment Away from Place of Insurance Registration</strong> (异地就医备案)</li><li>Enter <strong>Phone Number</strong></li><li>Select Registration Type: <strong>Long-term Residence Away from Place of Insurance (including university students)</strong> (异地长期居住（含在校大学生）)</li><li>Enter Place of Treatment: <strong>Destination Address</strong> (the city/hospital where you will receive treatment)</li><li>Enter Place of Insurance: <strong>School Address</strong></li><li>Select Material Type: <strong>Long-term Residence Certification Type</strong> (长期居住认定类型)</li><li>Click <strong>Next</strong></li><li><strong>Take a photo and upload</strong> the stamped registration form from Step 2.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Approval usually takes within 10 minutes.</p></div><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="q-how-long-does-it-take-for-the-registration-to-be-approved" tabindex="-1">Q: How long does it take for the registration to be approved? <a class="header-anchor" href="#q-how-long-does-it-take-for-the-registration-to-be-approved" aria-label="Permalink to &quot;Q: How long does it take for the registration to be approved?&quot;">​</a></h3><p>A: Generally, it takes 1-3 working days to complete the review after submission.</p><h3 id="q-why-is-medical-treatment-away-from-place-of-insurance-registration-required" tabindex="-1">Q: Why is &quot;Medical Treatment Away from Place of Insurance&quot; registration required? <a class="header-anchor" href="#q-why-is-medical-treatment-away-from-place-of-insurance-registration-required" aria-label="Permalink to &quot;Q: Why is &quot;Medical Treatment Away from Place of Insurance&quot; registration required?&quot;">​</a></h3><p>China&#39;s <strong>Basic Medical Insurance</strong> adopts a location-based management system, meaning the insured person&#39;s medical insurance relationship is bound to the place of insurance (Zhuhai). When you need to receive medical treatment in a city other than Zhuhai, it is considered &quot;Medical Treatment Away from Place of Insurance&quot;.</p><p>Without registration, you cannot settle expenses directly at designated medical institutions outside the insurance location by swiping the medical insurance card/code. You must <strong>pay all medical expenses out of pocket first</strong>, and then apply for manual reimbursement in Zhuhai.</p><p>Unregistered out-of-town medical treatment usually results in a <strong>significant reduction in reimbursement ratio</strong>, increasing the personal burden. Additionally, you must collect and mail back a large number of invoices and medical records, leading to a long approval cycle.</p><h3 id="q-benefits-of-registration" tabindex="-1">Q: Benefits of Registration <a class="header-anchor" href="#q-benefits-of-registration" aria-label="Permalink to &quot;Q: Benefits of Registration&quot;">​</a></h3><ul><li><strong>Direct Settlement</strong>: You can settle expenses directly at designated medical institutions outside the insurance location by swiping the medical insurance card/code, only paying the personal co-payment portion.</li><li><strong>Normal Reimbursement Ratio</strong>: It follows the &quot;Place of Treatment Catalog, Place of Insurance Policy&quot; rule, meaning drugs and diagnostic items follow the treatment location&#39;s regulations, and the reimbursement ratio follows Zhuhai&#39;s policy normally.</li></ul><h3 id="q-how-to-use" tabindex="-1">Q: How to use <a class="header-anchor" href="#q-how-to-use" aria-label="Permalink to &quot;Q: How to use&quot;">​</a></h3><p>Open the &quot;My Medical Insurance Certificate&quot; WeChat Mini Program, inform the staff and show the QR code when paying; or show the social security card.</p>',27)]))}const p=t(n,[["render",r]]);export{m as __pageData,p as default};
